package irvine.oeis.transform;

import irvine.math.z.Z;
import irvine.oeis.AbstractSequence;

/**
 * A sequence generated by transforming terms from other sequences, 
 * and selecting the non-null results only.
 * @author Georg Fischer
 */
public class FilterTransformSequence extends MultiTransformSequence {

  /**
   * See the corresponding description in {@MultiTransformSequence}. 
   * The lambda expression should return <code>null</code> in order to unselect the term for the target sequence.
   * @param offset offset of the new sequence
   * @param lambda function mapping (self, n) to the terms of the target sequence, 
   * or <code>null</code> if the term should not be included in the target sequence.
   * <code>n</code> is always the index in the source sequence(s).
   * @param initTerms initial terms for a(n)
   * @param seqs list underlying source sequences seq0, seq1, seq2 and so on
   */
  public FilterTransformSequence(final int offset, final MultiFunction<MultiTransformSequence, Long, Z> lambda,
                                 final String initTerms, final AbstractSequence... seqs) {
    super(offset, lambda, initTerms, seqs);
  }

  /**
   * Constructor without source sequences.
   * @param offset offset of the new sequence
   * @param lambda function mapping (self, n) to the terms of the target sequence
   * or <code>null</code> if the term should not be included in the target sequence.
   * <code>n</code> is always the index in the source sequence(s).
   * @param initTerms initial terms for a(n)
   */
  public FilterTransformSequence(final int offset, final MultiFunction<MultiTransformSequence, Long, Z> lambda,
                                final String initTerms) {
    this(offset, lambda, initTerms, new AbstractSequence[]{});
  }

  @Override
  public Z next() {
    while (true) {
      final Z result = super.next();
      if (result != null) {
        return result;
      }
    }
  }
}
